"""Review cards ("fichas"), one per finding of the review set, generated by script from the
checkouts at the pinned commits. A card holds facts only, never a verdict or an assessment:
  - the finding (rule, message, file:line, link to the file at the pinned commit);
  - the enclosing function, complete, with line numbers (Python: ast; Java: brace matching);
  - EVERY match of a literal search of that function's name in the repository
    (`git grep -n -w -F`, all tracked files, nothing filtered; a binary file is listed with its
    path, line "—" and text "binary file");
  - a path class for the finding and for every match (test / example-or-script / main).
The repository at the pinned commit is always linked and may be consulted freely.

  python3 scripts/cards.py <WORK>   -> cards/<id>.md and cards/SHA256SUMS (the sha256 of SHA256SUMS
                                       is published before the review starts)
"""
import ast
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path, PurePosixPath

DIR = Path(__file__).resolve().parent.parent
CONTEXT = 15  # lines around the finding when there is no enclosing function

TEST_SEGMENTS = {"test", "tests", "testing", "__tests__"}
TEST_FILE_RES = [re.compile(p) for p in (r"^test_.*\.py$", r"^.*_test\.py$", r"^conftest\.py$",
                                         r"^.*Tests?\.java$", r"^.*IT\.java$", r"^.*TestCase\.java$")]
NON_PROD_SEGMENTS = {"examples", "example", "scripts", "script", "wip", "spike", "demo", "demos",
                     "samples", "sample", "docs", "benchmark", "benchmarks"}


def classify_path(path):
    """test | example-or-script | main — descriptive only, from the path alone."""
    p = PurePosixPath(path)
    segments = [s.lower() for s in p.parts[:-1]]
    # Under a Java/Kotlin source root the segments are packages (com/example/demo is production).
    for i in range(len(segments) - 2):
        if segments[i:i + 3] in (["src", "main", "java"], ["src", "main", "kotlin"]):
            segments = segments[:i]
            break
    if any(s in TEST_SEGMENTS for s in segments) or "src/test/" in f"{path}/" or any(r.match(p.name) for r in TEST_FILE_RES):
        return "test"
    if any(s in NON_PROD_SEGMENTS for s in segments):
        return "example-or-script"
    return "main"


def python_enclosing(source, line):
    """(name, start, end) of the innermost def/async def containing `line` (decorators included), or None."""
    try:
        tree = ast.parse(source)
    except SyntaxError:
        return None
    best = None
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start = min([node.lineno] + [d.lineno for d in node.decorator_list])
            if start <= line <= node.end_lineno and (best is None or start >= best[1]):
                best = (node.name, start, node.end_lineno)
    return best


_JAVA_NOT_METHOD = {"if", "for", "while", "switch", "catch", "synchronized", "try", "else", "do", "return",
                    "new", "super", "this", "throw", "case"}
_JAVA_METHOD_RE = re.compile(r"(?:^|[\s>\]])([A-Za-z_$][\w$]*)\s*\((?:[^()]|\([^()]*\))*\)\s*(?:throws\s+[\w$.,\s<>]+)?$")


def java_blocks(source):
    """Every {…} block: (header, header_start_line, close_line), skipping comments, strings and chars."""
    blocks, stack = [], []
    header, header_start = [], None
    i, n, line = 0, len(source), 1
    while i < n:
        c = source[i]
        if source.startswith("//", i):
            j = source.find("\n", i)
            i = n if j < 0 else j
            continue
        if source.startswith("/*", i):
            j = source.find("*/", i + 2)
            j = n if j < 0 else j + 2
            line += source.count("\n", i, j)
            i = j
            continue
        if source.startswith('"""', i):
            j = source.find('"""', i + 3)
            j = n if j < 0 else j + 3
            line += source.count("\n", i, j)
            header.append('""')
            i = j
            continue
        if c in "\"'":
            j = i + 1
            while j < n and source[j] != c and source[j] != "\n":
                j += 2 if source[j] == "\\" else 1
            header.append(c + c)
            i = j + 1
            continue
        if c == "\n":
            line += 1
            header.append(" ")
        elif c == "{":
            stack.append((" ".join("".join(header).split()), header_start or line))
            header, header_start = [], None
        elif c == "}":
            if stack:
                h, start = stack.pop()
                blocks.append((h, start, line))
            header, header_start = [], None
        elif c == ";":
            header, header_start = [], None
        else:
            if header_start is None and not c.isspace():
                header_start = line
            header.append(c)
        i += 1
    return blocks


def java_method_name(header):
    m = _JAVA_METHOD_RE.search(header)
    if not m or m.group(1) in _JAVA_NOT_METHOD:
        return None
    before = header[:m.start(1)].split()
    if before and before[-1] == "new":
        return None
    return m.group(1)


def java_enclosing(source, line):
    """(name, start, end) of the innermost method or constructor containing `line`, or None."""
    best = None
    for header, start, end in java_blocks(source):
        name = java_method_name(header)
        if name and start <= line <= end and (best is None or start >= best[1]):
            best = (name, start, end)
    return best


def literal_matches(checkout, name):
    """Every match of `git grep -n -w -F` for the name in the checkout's tracked files, sorted."""
    r = subprocess.run(["git", "grep", "-n", "-w", "-F", "-e", name], cwd=checkout, capture_output=True, text=True, errors="replace")
    if r.returncode not in (0, 1):
        raise RuntimeError(f"git grep failed in {checkout}: {r.stderr.strip()}")
    out = []
    for row in r.stdout.splitlines():
        binary = re.fullmatch(r"Binary file (.+) matches", row)
        if binary:  # a binary tracked file has no line: listed with its path (DEVIATIONS.md §1, option a)
            path = binary.group(1)
            out.append({"path": path, "line": None, "class": classify_path(path), "text": "binary file"})
            continue
        path, ln, text = row.split(":", 2)
        out.append({"path": path, "line": int(ln), "class": classify_path(path), "text": text.strip()})
    return sorted(out, key=lambda m: (m["path"], m["line"] or 0))


def _cell(text, limit=200):
    text = text if len(text) <= limit else text[:limit] + " …"
    return text.replace("|", "\\|").replace("`", "'")


def render_card(f, source, matches):
    """The card's markdown. `source`: the file's text at the pinned commit; `matches`: literal_matches()."""
    lang = f["language"]
    lines = source.splitlines()
    enclosing = python_enclosing(source, f["line"]) if lang == "python" else java_enclosing(source, f["line"])
    anchor = f"#L{f['line']}" if f["line"] else ""
    md = [f"# {f['id']} · {f['ruleId']} · {f['repo']}", "",
          f"- Repository at the pinned commit (may be consulted freely): https://github.com/{f['repo']}/tree/{f['commit']}",
          f"- Location: [`{f['file']}:{f['line']}`](https://github.com/{f['repo']}/blob/{f['commit']}/{f['file']}{anchor}) · path class: {classify_path(f['file'])}",
          f"- Rule: `{f['ruleId']}` ({f.get('engine', '')}), severity {f['severity']}",
          f"- Message: {f['message']}", ""]
    if enclosing:
        name, start, end = enclosing
        md += [f"## Enclosing function `{name}` (lines {start}–{end})", ""]
    else:
        name, start, end = None, max(1, f["line"] - CONTEXT), min(len(lines), f["line"] + CONTEXT)
        md += [f"## No enclosing function: lines {start}–{end}", ""]
    md.append(f"```{lang}")
    width = len(str(end))
    for k in range(start, end + 1):
        mark = ">" if k == f["line"] else " "
        md.append(f"{mark}{str(k).rjust(width)}  {lines[k - 1] if k - 1 < len(lines) else ''}")
    md += ["```", ""]
    if name:
        md += [f"## Literal search of `{name}` in the repository", "",
               f"`git grep -n -w -F -e {name}` over every tracked file at the pinned commit: **{len(matches)} matches**, all listed.", ""]
        if matches:
            md += ["| path | line | path class | text |", "|---|---|---|---|"]
            md += [f"| {_cell(m['path'], 300)} | {m['line'] if m['line'] is not None else '—'} | {m['class']} | `{_cell(m['text'])}` |" for m in matches]
        md.append("")
    else:
        md += ["## Literal search", "", "No enclosing function, so no name to search.", ""]
    md += ["---", "Generated by `scripts/cards.py` from the checkout at the pinned commit. Facts only."]
    return "\n".join(md) + "\n"


def main(work):
    out = DIR / "cards"
    if out.exists():
        raise SystemExit("cards/ exists: the cards are generated once, before the review")
    rs = json.loads((DIR / "review-set.json").read_text())["findings"]
    out.mkdir()
    sums = []
    for f in rs:
        checkout = Path(work) / f["language"] / f["repo"].replace("/", "__")
        head = subprocess.run(["git", "rev-parse", "HEAD"], cwd=checkout, capture_output=True, text=True).stdout.strip()
        if head != f["commit"]:
            raise SystemExit(f"{f['id']}: checkout {checkout} is at {head}, not {f['commit']}")
        source = (checkout / f["file"]).read_text(encoding="utf-8", errors="replace")
        enclosing = python_enclosing(source, f["line"]) if f["language"] == "python" else java_enclosing(source, f["line"])
        matches = literal_matches(checkout, enclosing[0]) if enclosing else []
        text = render_card(f, source, matches)
        (out / f"{f['id']}.md").write_text(text)
        sums.append(f"{hashlib.sha256(text.encode()).hexdigest()}  {f['id']}.md")
    (out / "SHA256SUMS").write_text("\n".join(sorted(sums, key=lambda s: s.split()[1])) + "\n")
    print(f"{len(rs)} cards; sha256 of cards/SHA256SUMS: {hashlib.sha256((out / 'SHA256SUMS').read_bytes()).hexdigest()}")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit(__doc__)
    main(sys.argv[1])
